   while(boxes.length<count){let best=-1,score=-1,axis='r';boxes.forEach((box,i)=>{if(box.length<2)return;const w=box.reduce((s,c)=>s+c.w,0);for(const k of ['r','g','b']){let lo=255,hi=0;box.forEach(c=>{lo=Math.min(lo,c[k]);hi=Math.max(hi,c[k]);});const s=(hi-lo)*Math.sqrt(w);if(s>score){score=s;best=i;axis=k;}}});if(best<0)break;const box=boxes[best].sort((a,b)=>a[axis]-b[axis]);const half=box.reduce((s,c)=>s+c.w,0)/2;let sum=0,mid=1;for(let i=0;i<box.length-1;i++){sum+=box[i].w;if(sum>=half){mid=i+1;break;}mid=i+1;}boxes.splice(best,1,box.slice(0,mid),box.slice(mid));}
   const pal=boxes.map(box=>{const w=box.reduce((s,c)=>s+c.w,0);return {r:Math.round(box.reduce((s,c)=>s+c.r*c.w,0)/w),g:Math.round(box.reduce((s,c)=>s+c.g*c.w,0)/w),b:Math.round(box.reduce((s,c)=>s+c.b*c.w,0)/w),a:255};});
