 function objects(td){if(td.graph)root.VectorGraph.sync(td);const list=[];td.layers.forEach((layer,li)=>{if(td.palette[li].a===0)return;layer.forEach(path=>{if(path.isholepath||!path.segments.length)return;list.push({color:td.palette[li],layer:li,paths:[path,...path.holechildren.map(h=>layer[h]).filter(Boolean)]});});});if(td.outlineLayer&&td.palette[td.outlineLayer.color]?.a>0){const layer=td.outlineLayer.paths;layer.forEach(path=>{if(path.isholepath||!path.segments.length)return;list.push({color:td.palette[td.outlineLayer.color],layer:td.outlineLayer.color,outlineOverlay:true,paths:[path,...path.holechildren.map(i=>layer[i]).filter(Boolean)]});});}return list;}
