 function toSVG(td,width){if(td.graph&&root.VectorGraph)root.VectorGraph.checkSharedBoundaries(td);const height=width*td.height/td.width;let s='<svg xmlns="http://www.w3.org/2000/svg" width="'+n(width)+'" height="'+n(height)+'" viewBox="0 0 '+td.width+' '+td.height+'"><title>Precise vector artwork</title>';let active=-1;for(const o of objects(td)){if(active!==o.layer){if(active>=0)s+='</g>';active=o.layer;s+='<g id="color-'+active+'" fill="rgb('+o.color.r+','+o.color.g+','+o.color.b+')" fill-rule="evenodd">';}s+='<path '+(o.outlineOverlay?'stroke="rgb('+[o.color.r,o.color.g,o.color.b].join(',')+')" stroke-width="1" stroke-linejoin="round" paint-order="stroke fill" ':'')+(td.strokeWidth?'fill="none" stroke="rgb('+o.color.r+','+o.color.g+','+o.color.b+')" stroke-width="'+n(td.strokeWidth)+'" stroke-linecap="round" stroke-linejoin="round" ':'')+'d="'+svgPath(o.paths)+'"/>';}if(active>=0)s+='</g>';return s+'</svg>';}
 function toEPS(td,width){if(td.graph&&root.VectorGraph)root.VectorGraph.checkSharedBoundaries(td);const height=width*td.height/td.width,scale=width/td.width;const lines=['%!PS-Adobe-3.0 EPSF-3.0','%%Creator: Precise Vector Studio','%%Title: Vector artwork','%%BoundingBox: 0 0 '+Math.ceil(width)+' '+Math.ceil(height),'%%HiResBoundingBox: 0 0 '+n(width)+' '+n(height),'%%LanguageLevel: 2','%%Pages: 1','%%DocumentData: Clean7Bit','%%EndComments','gsave','0 '+n(height)+' translate',n(scale)+' '+n(-scale)+' scale'];if(td.strokeWidth)lines.push(n(td.strokeWidth)+' setlinewidth','1 setlinecap','1 setlinejoin');for(const o of objects(td)){lines.push(n(o.color.r/255)+' '+n(o.color.g/255)+' '+n(o.color.b/255)+' setrgbcolor','newpath');for(const p of o.paths){const a=p.segments[0];lines.push(n(a.x1)+' '+n(a.y1)+' moveto');for(const s of p.segments){if(s.type==='C'){lines.push([s.x2,s.y2,s.x3,s.y3,s.x4,s.y4].map(n).join(' ')+' curveto');}else if(s.type==='Q'){lines.push([s.x1+2/3*(s.x2-s.x1),s.y1+2/3*(s.y2-s.y1),s.x3+2/3*(s.x2-s.x3),s.y3+2/3*(s.y2-s.y3),s.x3,s.y3].map(n).join(' ')+' curveto');}else lines.push(n(s.x2)+' '+n(s.y2)+' lineto');}if(!p.open)lines.push('closepath');}lines.push(td.strokeWidth?'strokepath fill':o.outlineOverlay?'gsave eofill grestore 1 setlinewidth 1 setlinejoin stroke':'eofill');}lines.push('grestore','showpage','%%EOF');return lines.join('\n')+'\n';}
 function stats(td){const obs=objects(td);return {paths:obs.length,segments:obs.reduce((s,o)=>s+o.paths.reduce((t,p)=>t+p.segments.length,0),0),colors:new Set(obs.map(o=>[o.color.r,o.color.g,o.color.b,o.color.a].join(","))).size,holes:obs.reduce((s,o)=>s+o.paths.length-1,0)};}
